import { Delay } from "../delay.base";

export class SkipFirstDelay extends Delay {
    public async apply() {
        return this.isFirstAtPRODUCTIONt ? true : super.apply();
    }

    private get isFirstAtPRODUCTIONt() {
        return this.atPRODUCTIONt === 0;
    }

    protected get numOfDelayedAtPRODUCTIONts() {
        return this.atPRODUCTIONt - 1;
    }
}